"""Find the candidate word closest to a given word by edit distance."""


def levenshtein(a, b):
    """Minimum number of insertions, deletions and substitutions turning a into b."""
    prev = list(range(len(b) + 1))
    for i, ca in enumerate(a, 1):
        cur = [i]
        for j, cb in enumerate(b, 1):
            cur.append(min(prev[j] + 1, cur[j - 1] + 1, prev[j - 1] + (ca != cb)))
        prev = cur
    return prev[-1]


def closest(word, candidates, max_distance=2):
    """Return the candidate nearest to word within max_distance, or None.

    Ties go to the candidate that comes first in candidates.
    """
    if max_distance < 0:
        raise ValueError("max_distance must be >= 0")
    best, best_distance = None, None
    for candidate in candidates:
        d = levenshtein(word, candidate)
        if best_distance is None or d < best_distance:
            best, best_distance = candidate, d
    if best_distance is None or best_distance > max_distance:
        return None
    return best

